code.cpp:
class Solution {
public:
    int kthFactor(int n, int k) {
        int i;
        for (i = 1; i * i <= n; i++) {
            if (n % i == 0) {
                k--;
                if (k == 0) return i;
            }
        }
        i--;
        if (i * i == n) i--;
        for (; i >= 1; i--) {
            if (n % i == 0) {
                k--;
                if (k == 0) return n / i;
            }
        }
        return -1;
    }
};
